import json, re

OUT = "/tmp/obench-cell-7m2c0hm_/bench_opencode_regex-chess_3ttzyhor/re.json"
R = []
def add(p, r): R.append([p, r])

def rc(i): return divmod(i, 8)
def idx(r, c): return r * 8 + c
def onb(r, c): return 0 <= r < 8 and 0 <= c < 8

def pos_pattern(cons):
    """cons: dict index->regex class; returns pattern from board start."""
    out, cur = [], 0
    for i in sorted(cons):
        gap = i - cur
        if gap: out.append('.{%d}' % gap)
        out.append(cons[i]); cur = i + 1
    return ''.join(out)

KN = [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]
KG = [(a,b) for a in (-1,0,1) for b in (-1,0,1) if (a,b)!=(0,0)]
ORTH = [(1,0),(-1,0),(0,1),(0,-1)]
DIAG = [(1,1),(1,-1),(-1,1),(-1,-1)]

def attack_alts(s):
    r, c = rc(s); alts = []
    for dr, dc in KN:
        if onb(r+dr, c+dc): alts.append(pos_pattern({idx(r+dr,c+dc): 'n'}))
    for dr, dc in KG:
        if onb(r+dr, c+dc): alts.append(pos_pattern({idx(r+dr,c+dc): 'k'}))
    for dc in (-1, 1):  # black pawn one row up (lower r)
        if onb(r-1, c+dc): alts.append(pos_pattern({idx(r-1,c+dc): 'p'}))
    for dirs, cls in ((ORTH, '[rq]'), (DIAG, '[bq]')):
        for dr, dc in dirs:
            path = []
            rr, cc = r+dr, c+dc
            while onb(rr, cc):
                cons = {p: r'\.' for p in path}
                cons[idx(rr,cc)] = cls
                alts.append(pos_pattern(cons))
                path.append(idx(rr,cc)); rr += dr; cc += dc
    return '(?:' + '|'.join(alts) + ')'

ATT = [attack_alts(s) for s in range(64)]

# ---------- preprocessing ----------
for n in range(8, 0, -1):
    add(str(n) + r'(?=[^ ]* w )', '.' * n)
add(r'/(?=[^ ]* w )', '')
add(r'^(.{64}) w (\S+) (\S+).*$', r'O:\1 \2 \3')
def norm(s):
    return ''.join(ch if ch in s else '-' for ch in 'KQkq')
import itertools
subs = []
for m in range(16):
    s = ''.join(ch for i, ch in enumerate('KQkq') if m >> i & 1) or '-'
    add(r'^(O:.{64}) ' + s + ' ', r'\1 ' + norm(s) + ' ')

# ---------- move generation ----------
def gen(cons, mods, extra=''):
    """cons: index->class (all constraints incl. modified squares);
    mods: index->new char."""
    look = {i: v for i, v in cons.items() if i not in mods}
    pat = '^O:' + extra
    if look: pat += '(?=' + pos_pattern(look) + ')'
    cur = 0; g = 1; rep = r'\g<0>\nC:'
    for i in sorted(mods):
        pat += '(.{%d})' % (i - cur) + cons[i]
        rep += '\\%d' % g + mods[i] if g < 10 else '\\g<%d>' % g + mods[i]
        g += 1; cur = i + 1
    pat += '(.*)$'
    rep += '\\g<%d>' % g
    add(pat, rep)

TGT = '[.pnbrq]'
for s in range(64):
    r, c = rc(s)
    # knight / king
    for piece, offs in (('N', KN), ('K', KG)):
        for dr, dc in offs:
            if onb(r+dr, c+dc):
                t = idx(r+dr, c+dc)
                gen({s: piece, t: TGT}, {s: '.', t: piece})
    # sliders
    for piece, dirs in (('R', ORTH), ('B', DIAG), ('Q', ORTH + DIAG)):
        for dr, dc in dirs:
            path = []; rr, cc = r+dr, c+dc
            while onb(rr, cc):
                t = idx(rr, cc)
                cons = {p: r'\.' for p in path}
                cons[s] = piece; cons[t] = TGT
                gen(cons, {s: '.', t: piece})
                path.append(t); rr += dr; cc += dc
    # pawns (white moves to lower r)
    if 1 <= r <= 6:
        np = 'Q' if r == 1 else 'P'
        t = idx(r-1, c)
        gen({s: 'P', t: r'\.'}, {s: '.', t: np})
        if r == 6:
            gen({s: 'P', t: r'\.', idx(4, c): r'\.'}, {s: '.', idx(4, c): 'P'})
        for dc in (-1, 1):
            if onb(r-1, c+dc):
                t = idx(r-1, c+dc)
                gen({s: 'P', t: TGT}, {s: '.', t: np})
# en passant: white pawn on rank 5 (r=3) captures to r=2
for c in range(8):
    sq = 'abcdefgh'[c] + '6'
    for dc in (-1, 1):
        if onb(3, c+dc):
            s = idx(3, c+dc)
            gen({s: 'P', idx(3, c): 'p', idx(2, c): r'\.', 70: sq[0], 71: sq[1]},
                {s: '.', idx(3, c): '.', idx(2, c): 'P'})
# castling
gen({60: 'K', 61: r'\.', 62: r'\.', 63: 'R', 65: 'K'},
    {60: '.', 61: 'R', 62: 'K', 63: '.'},
    '(?!' + ATT[60] + ')(?!' + ATT[61] + ')')
gen({56: 'R', 57: r'\.', 58: r'\.', 59: r'\.', 60: 'K', 66: 'Q'},
    {56: '.', 58: 'K', 59: 'R', 60: '.'},
    '(?!' + ATT[60] + ')(?!' + ATT[59] + ')')

# ---------- legality filter ----------
for k in range(64):
    add(r'\nC:(?=.{%d}K)(?=%s)[^\n]*' % (k, ATT[k]), '')

# ---------- castling rights ----------
add(r'(?m)^(C:.{60}[^K].{4})K', r'\1-')
add(r'(?m)^(C:.{60}[^K].{5})Q', r'\1-')
add(r'(?m)^(C:.{63}[^R] )K', r'\1-')
add(r'(?m)^(C:.{56}[^R].{9})Q', r'\1-')
add(r'(?m)^(C:.{4}[^k].{62})k', r'\1-')
add(r'(?m)^(C:.{4}[^k].{63})q', r'\1-')
add(r'(?m)^(C:.{7}[^r].{59})k', r'\1-')
add(r'(?m)^(C:[^r].{67})q', r'\1-')

# ---------- output ----------
add(r'^O:[^\n]*\n?', '')
add(r'(?m)^C:' + '(.{8})' * 8 + r' (\S+) \S+$',
    r'\1/\2/\3/\4/\5/\6/\7/\8 b \9 - 0 0')
for m in range(16):
    s = ''.join(ch for i, ch in enumerate('KQkq') if m >> i & 1) or '-'
    add(r'(?m) b ' + re.escape(norm(s)) + ' ', ' b ' + s + ' ')
for n in range(8, 0, -1):
    add(r'\.{%d}' % n, str(n))

json.dump(R, open(OUT, 'w'))
print(len(R), "rules")
